// Frozen Unicode lowercase used for vocabulary identity. It is generated by
// scripts/generate-unicode-casing.js and mirrors plugin/unicode_lower.lua, so
// identities do not change when the Node.js runtime (ICU) is upgraded.
import { readFileSync } from 'node:fs';
const data = JSON.parse(readFileSync(new URL('./unicode-casing.json', import.meta.url), 'utf8'));
export const UNICODE_VERSION = data.version;
const mapping = new Map(Object.entries(data.map).map(([key, value]) => [Number(key), value]));
function contains(ranges, n) {
  let low = 0, high = ranges.length - 1;
  while (low <= high) {
    const mid = (low + high) >> 1, [first, last] = ranges[mid];
    if (n < first) high = mid - 1; else if (n > last) low = mid + 1; else return true;
  }
  return false;
}
export function lower(value) {
  const points = Array.from(value, char => char.codePointAt(0));
  const casedFrom = (index, step) => {
    for (; index >= 0 && index < points.length; index += step) {
      if (!contains(data.ignorable, points[index])) return contains(data.cased, points[index]);
    }
    return false;
  };
  let out = '';
  points.forEach((point, index) => {
    const mapped = point === 0x3a3 && casedFrom(index - 1, -1) && !casedFrom(index + 1, 1) ? [0x3c2] : mapping.get(point) ?? [point];
    out += String.fromCodePoint(...mapped);
  });
  return out;
}
